import { css, FlattenSimpleInterpolation } from 'styled-components';

import Colors from '@dynatrace/strato-design-tokens/colors';
import Elevations from '@dynatrace/strato-design-tokens/elevations';

export const StyledStickyHeaderCss: FlattenSimpleInterpolation = css`
  [data-stickyheader] & {
    // Sorting behaviour adds position: relative to the element styles via
    // hook. Either we use the important here to override, or we move the
    // sticky header styling to inline styles as well.
    // REVIEW: Opinions are welcome, as I'm not quite happy with this.
    position: sticky !important;
    top: 0;
    z-index: ${Elevations.Sticky};

    // todo: add real background overlay style as soon as ux has one.
    background: ${Colors.Background.Surface.Default};
  }
`;
